; cost.asm -- chapter 11: every kind of jump, call and return, taken and not
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "cost.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; Every jump, call and return, taken and not, each instruction with a
; label for the debugger to stop at. A HALT marks a place no jump should
; land: with the interrupts off it would stop the program for good.
init:   di
        ld sp, SYS_AREA
        xor a                   ; Z = 1
c1:     jp z, c2                ; JP cc, taken
        halt
c2:     jp nz, never            ; JP cc, not taken
c3:     jp c4                   ; JP
        halt
c4:     jr z, c5                ; JR cc, taken
        halt
c5:     jr nz, never            ; JR cc, not taken
c6:     jr c7                   ; JR
        halt
c7:     ld b, 2
c8:     djnz c8                 ; DJNZ, taken once and then not
c9:     call z, sub             ; CALL cc, taken
c10:    call nz, never          ; CALL cc, not taken
c11:    call sub2               ; CALL
c12:    ld hl, c14
c13:    jp (hl)                 ; JP (HL)
        halt
c14:    ld ix, c16
c15:    jp (ix)                 ; JP (IX)
        halt
c16:    nop
stop:   jr stop

sub:    ret nz                  ; RET cc, not taken
s2:     ret z                   ; RET cc, taken
sub2:   ret                     ; RET
never:  halt
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
